#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct ModelKey {
    backend_id: String,
    model_id: String,
    execution_environment: Option<String>,
}

impl ModelKey {
    fn from_config(config: &NativeModelConfig) -> Self {
        Self {
            backend_id: config.backend_id().to_owned(),
            model_id: config.model_id(),
            execution_environment: config
                .execution_environment_id()
                .map(ToOwned::to_owned),
        }
    }

    fn matches_record(&self, record: &BenchmarkRecord) -> bool {
        record.identity.model.backend_id == self.backend_id
            && record.identity.model.model_id == self.model_id
            && self.execution_environment.as_ref().is_none_or(|environment| {
                matches!(
                    &record.identity.model.execution_environment,
                    TelemetryValue::Measured(recorded) if recorded == environment
                )
            })
    }
}
